package gal.rodrigosambade.cameraxlab;
import android.Manifest; import android.content.ContentValues; import android.content.pm.PackageManager; import android.os.Bundle; import android.provider.MediaStore; import android.widget.*;
import androidx.activity.result.*; import androidx.activity.result.contract.ActivityResultContracts; import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity; import androidx.camera.core.*; import androidx.camera.lifecycle.ProcessCameraProvider; import androidx.camera.video.*; import androidx.camera.view.PreviewView; import androidx.core.content.ContextCompat;
import com.google.common.util.concurrent.ListenableFuture; import java.nio.ByteBuffer; import java.text.SimpleDateFormat; import java.util.*; import java.util.concurrent.*;
public class MainActivity extends AppCompatActivity {
 PreviewView previewView; TextView status; Button videoButton; ExecutorService executor; ImageCapture imageCapture; VideoCapture<Recorder> videoCapture; Recording recording; CameraSelector selector=CameraSelector.DEFAULT_BACK_CAMERA;
 ActivityResultLauncher<String[]> permissions=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->{if(Boolean.TRUE.equals(r.get(Manifest.permission.CAMERA)))startCamera();else status.setText("Se necesita CAMERA");});
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);previewView=findViewById(R.id.preview);status=findViewById(R.id.status);videoButton=findViewById(R.id.video);executor=Executors.newSingleThreadExecutor();findViewById(R.id.photo).setOnClickListener(v->takePhoto());videoButton.setOnClickListener(v->toggleVideo());findViewById(R.id.switchCamera).setOnClickListener(v->{selector=selector==CameraSelector.DEFAULT_BACK_CAMERA?CameraSelector.DEFAULT_FRONT_CAMERA:CameraSelector.DEFAULT_BACK_CAMERA;startCamera();});if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)startCamera();else permissions.launch(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO});}
 void startCamera(){ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{ProcessCameraProvider p=f.get();Preview pr=new Preview.Builder().build();pr.setSurfaceProvider(previewView.getSurfaceProvider());imageCapture=new ImageCapture.Builder().build();videoCapture=VideoCapture.withOutput(new Recorder.Builder().build());ImageAnalysis a=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();a.setAnalyzer(executor,this::analyze);p.unbindAll();p.bindToLifecycle(this,selector,pr,imageCapture,videoCapture,a);}catch(Exception e){status.setText(e.toString());}},ContextCompat.getMainExecutor(this));}
 void analyze(@NonNull ImageProxy image){try{ByteBuffer b=image.getPlanes()[0].getBuffer();long s=0;int n=0;while(b.hasRemaining()){s+=b.get()&255;n++;}int l=n==0?0:(int)(s/n);runOnUiThread(()->status.setText("Luminancia Y: "+l+" · "+image.getWidth()+"×"+image.getHeight()));}finally{image.close();}}
 String stamp(){return new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date());}
 void takePhoto(){if(imageCapture==null)return;ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"CAMERAX_"+stamp());v.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");ImageCapture.OutputFileOptions o=new ImageCapture.OutputFileOptions.Builder(getContentResolver(),MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v).build();imageCapture.takePicture(o,ContextCompat.getMainExecutor(this),new ImageCapture.OnImageSavedCallback(){public void onImageSaved(@NonNull ImageCapture.OutputFileResults r){Toast.makeText(MainActivity.this,"Foto: "+r.getSavedUri(),Toast.LENGTH_SHORT).show();}public void onError(@NonNull ImageCaptureException e){status.setText(e.toString());}});}
 void toggleVideo(){if(recording!=null){recording.stop();return;}if(videoCapture==null)return;ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.DISPLAY_NAME,"CAMERAX_"+stamp());v.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");MediaStoreOutputOptions o=new MediaStoreOutputOptions.Builder(getContentResolver(),MediaStore.Video.Media.EXTERNAL_CONTENT_URI).setContentValues(v).build();PendingRecording p=videoCapture.getOutput().prepareRecording(this,o);if(ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)p=p.withAudioEnabled();recording=p.start(ContextCompat.getMainExecutor(this),e->{if(e instanceof VideoRecordEvent.Start)videoButton.setText("Detener");if(e instanceof VideoRecordEvent.Finalize){VideoRecordEvent.Finalize x=(VideoRecordEvent.Finalize)e;recording=null;videoButton.setText("Grabar");status.setText(x.hasError()?"Error vídeo "+x.getError():"Vídeo: "+x.getOutputResults().getOutputUri());}});}
 protected void onDestroy(){if(recording!=null)recording.close();executor.shutdown();super.onDestroy();}
}
